// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Service health
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListActionPolicies List every action policy
	// (GET /v1/action-policies)
	ListActionPolicies(ctx context.Context, request ListActionPoliciesRequestObject) (ListActionPoliciesResponseObject, error)
	// DeleteActionPolicy Remove an action policy; the template's actions are denied by default from then on
	// (DELETE /v1/action-policies/{name})
	DeleteActionPolicy(ctx context.Context, request DeleteActionPolicyRequestObject) (DeleteActionPolicyResponseObject, error)

	// (GET /v1/action-policies/{name})
	GetActionPolicy(ctx context.Context, request GetActionPolicyRequestObject) (GetActionPolicyResponseObject, error)
	// ApplyActionPolicy Create or change an action policy; at most one applies to a template
	// (PUT /v1/action-policies/{name})
	ApplyActionPolicy(ctx context.Context, request ApplyActionPolicyRequestObject) (ApplyActionPolicyResponseObject, error)
	// ListCatalogue Template versions published to the catalogue (assignable to joiners)
	// (GET /v1/catalogue)
	ListCatalogue(ctx context.Context, request ListCatalogueRequestObject) (ListCatalogueResponseObject, error)

	// (GET /v1/catalogue/requests)
	ListCatalogueRequests(ctx context.Context, request ListCatalogueRequestsRequestObject) (ListCatalogueRequestsResponseObject, error)
	// DecideCatalogueRequest Approve or reject (catalogue approvers only; never the requester, never twice)
	// (POST /v1/catalogue/requests/{id}/decision)
	DecideCatalogueRequest(ctx context.Context, request DecideCatalogueRequestRequestObject) (DecideCatalogueRequestResponseObject, error)
	// WithdrawFromCatalogue Withdraw a template; new joiners stop receiving it, existing instances are untouched
	// (DELETE /v1/catalogue/{name})
	WithdrawFromCatalogue(ctx context.Context, request WithdrawFromCatalogueRequestObject) (WithdrawFromCatalogueResponseObject, error)
	// ListEvents Export the tenant's evidence chain in seq order
	// (GET /v1/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// ReceiveHrEvent Receive a joiner or leaver event from the HR system
	// (POST /v1/hr/events)
	ReceiveHrEvent(ctx context.Context, request ReceiveHrEventRequestObject) (ReceiveHrEventResponseObject, error)
	// ListInstances List instances
	// (GET /v1/instances)
	ListInstances(ctx context.Context, request ListInstancesRequestObject) (ListInstancesResponseObject, error)
	// GetInstance Get an instance
	// (GET /v1/instances/{name})
	GetInstance(ctx context.Context, request GetInstanceRequestObject) (GetInstanceResponseObject, error)
	// ApplyInstance Create an instance, or update its sponsor, delegate and cost centre
	// (PUT /v1/instances/{name})
	ApplyInstance(ctx context.Context, request ApplyInstanceRequestObject) (ApplyInstanceResponseObject, error)
	// TransitionInstance Move an instance to another lifecycle state
	// (POST /v1/instances/{name}/transitions)
	TransitionInstance(ctx context.Context, request TransitionInstanceRequestObject) (TransitionInstanceResponseObject, error)
	// ListLinks List every agent link
	// (GET /v1/links)
	ListLinks(ctx context.Context, request ListLinksRequestObject) (ListLinksResponseObject, error)
	// DeleteLink Remove a link; calls it allowed are denied from then on
	// (DELETE /v1/links/{name})
	DeleteLink(ctx context.Context, request DeleteLinkRequestObject) (DeleteLinkResponseObject, error)

	// (GET /v1/links/{name})
	GetLink(ctx context.Context, request GetLinkRequestObject) (GetLinkResponseObject, error)
	// ApplyLink Create or change an agent link; an identical document changes nothing
	// (PUT /v1/links/{name})
	ApplyLink(ctx context.Context, request ApplyLinkRequestObject) (ApplyLinkResponseObject, error)
	// GetCompiledPolicies The Cedar policy set the tenant's rules compile to
	// (GET /v1/policy/cedar)
	GetCompiledPolicies(ctx context.Context, request GetCompiledPoliciesRequestObject) (GetCompiledPoliciesResponseObject, error)
	// DecidePolicy Decide an agent call or tool action (observe mode; recorded as evidence)
	// (POST /v1/policy/decisions)
	DecidePolicy(ctx context.Context, request DecidePolicyRequestObject) (DecidePolicyResponseObject, error)
	// SimulatePolicy Decide a request under the current and proposed rules, changing nothing
	// (POST /v1/policy/simulate)
	SimulatePolicy(ctx context.Context, request SimulatePolicyRequestObject) (SimulatePolicyResponseObject, error)
	// ExportPersonalData Export everything held about a person (privacy officers, or the person themselves)
	// (POST /v1/privacy/access)
	ExportPersonalData(ctx context.Context, request ExportPersonalDataRequestObject) (ExportPersonalDataResponseObject, error)
	// ErasePersonalData Erase a person's data (privacy officers only); repeating an id returns the stored proof
	// (POST /v1/privacy/erasures)
	ErasePersonalData(ctx context.Context, request ErasePersonalDataRequestObject) (ErasePersonalDataResponseObject, error)
	// GetErasure The proof of a completed erasure (privacy officers only)
	// (GET /v1/privacy/erasures/{id})
	GetErasure(ctx context.Context, request GetErasureRequestObject) (GetErasureResponseObject, error)
	// ListTemplates List the latest version of every template
	// (GET /v1/templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// GetTemplate Get the latest version of a template
	// (GET /v1/templates/{name})
	GetTemplate(ctx context.Context, request GetTemplateRequestObject) (GetTemplateResponseObject, error)
	// ApplyTemplate Apply a template; a changed document creates a new immutable version
	// (PUT /v1/templates/{name})
	ApplyTemplate(ctx context.Context, request ApplyTemplateRequestObject) (ApplyTemplateResponseObject, error)
	// GetTemplateVersion Get one version of a template
	// (GET /v1/templates/{name}/versions/{version})
	GetTemplateVersion(ctx context.Context, request GetTemplateVersionRequestObject) (GetTemplateVersionResponseObject, error)
	// RequestPublication Ask for this template version to be published to the catalogue
	// (POST /v1/templates/{name}/versions/{version}/publication)
	RequestPublication(ctx context.Context, request RequestPublicationRequestObject) (RequestPublicationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

